// Case-sensitive
const b = ['Apple', 'apple', 'APPLE', 'apple'];
const r2 = uniqueStrings(b);
console.log('case:', JSON.stringify(r2));
console.assert(JSON.stringify(r2) === JSON.stringify(['Apple','apple','APPLE']), 'case failed');

// Whitespace not trimmed
const c = ['a', ' a', 'a ', 'a'];
const r3 = uniqueStrings(c);
console.log('whitespace:', JSON.stringify(r3));
console.assert(JSON.stringify(r3) === JSON.stringify(['a',' a','a ']), 'whitespace failed');

// Input not mutated
const d = ['x', 'y', 'x'];
const snapshot = JSON.stringify(d);
uniqueStrings(d);
console.assert(JSON.stringify(d) === snapshot, 'mutation detected');

// Empty array
console.log('empty:', JSON.stringify(uniqueStrings([])));

// Single element
console.log('single:', JSON.stringify(uniqueStrings(['only'])));

